func removeInvalidParentheses(s string) []string {
	vis := map[string]bool{}
	l, r, n := 0, 0, len(s)
	for _, c := range s {
		if c == '(' {
			l++
		} else if c == ')' {
			if l > 0 {
				l--
			} else {
				r++
			}
		}
	}
	var dfs func(i, l, r, lcnt, rcnt int, t string)
	dfs = func(i, l, r, lcnt, rcnt int, t string) {
		if i == n {
			if l == 0 && r == 0 {
				vis[t] = true
			}
			return
		}
		if n-i < l+r || lcnt < rcnt {
			return
		}
		if s[i] == '(' && l > 0 {
			dfs(i+1, l-1, r, lcnt, rcnt, t)
		}
		if s[i] == ')' && r > 0 {
			dfs(i+1, l, r-1, lcnt, rcnt, t)
		}
		x, y := 0, 0
		if s[i] == '(' {
			x = 1
		} else if s[i] == ')' {
			y = 1
		}
		dfs(i+1, l, r, lcnt+x, rcnt+y, t+string(s[i]))
	}
	dfs(0, l, r, 0, 0, "")
	ans := make([]string, 0, len(vis))
	for v := range vis {
		ans = append(ans, v)
	}
	return ans
}

function removeInvalidParentheses(s: string): string[] {
    const n = s.length;
    let l = 0,
        r = 0;
    for (const c of s) {
        if (c === '(') {
            l++;
        } else if (c === ')') {
            if (l > 0) {
                l--;
            } else {
                r++;
            }
        }
    }

    const ans = new Set<string>();

    const dfs = (i: number, l: number, r: number, lcnt: number, rcnt: number, t: string): void => {
        if (i === n) {
            if (l === 0 && r === 0) {
                ans.add(t);
            }
            return;
        }
        if (n - i < l + r || lcnt < rcnt) {
            return;
        }
        const c = s[i];
        if (c === '(' && l > 0) {
            dfs(i + 1, l - 1, r, lcnt, rcnt, t);
        }
        if (c === ')' && r > 0) {
            dfs(i + 1, l, r - 1, lcnt, rcnt, t);
        }
        const x = c === '(' ? 1 : 0;
        const y = c === ')' ? 1 : 0;
        dfs(i + 1, l, r, lcnt + x, rcnt + y, t + c);
    };

    dfs(0, l, r, 0, 0, '');
    return Array.from(ans);
}

use std::collections::HashSet;

impl Solution {
    pub fn remove_invalid_parentheses(s: String) -> Vec<String> {
        let s = s.into_bytes();
        let mut l = 0;
        let mut r = 0;
        for &c in &s {
            if c == b'(' {
                l += 1;
            } else if c == b')' {
                if l > 0 {
                    l -= 1;
                } else {
                    r += 1;
                }
            }
        }
        let mut ans = HashSet::new();

        fn dfs(
            s: &[u8],
            i: usize,
            l: usize,
            r: usize,
            lcnt: usize,
            rcnt: usize,
            t: &mut Vec<u8>,
            ans: &mut HashSet<String>,
        ) {
            let n = s.len();
            if i == n {
                if l == 0 && r == 0 {
                    ans.insert(String::from_utf8(t.clone()).unwrap());
                }
                return;
            }
            if n - i < l + r || lcnt < rcnt {
                return;
            }
            let c = s[i];
            if c == b'(' && l > 0 {
                dfs(s, i + 1, l - 1, r, lcnt, rcnt, t, ans);
            }
            if c == b')' && r > 0 {
                dfs(s, i + 1, l, r - 1, lcnt, rcnt, t, ans);
            }
            let x = if c == b'(' { 1 } else { 0 };
            let y = if c == b')' { 1 } else { 0 };
            t.push(c);
            dfs(s, i + 1, l, r, lcnt + x, rcnt + y, t, ans);
            t.pop();
        }

        dfs(&s, 0, l, r, 0, 0, &mut Vec::new(), &mut ans);
        ans.into_iter().collect()
    }
}
